INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('bb3947db-cd58-51cb-8acc-994231713777','TEXT','Proofreading passage PD','The students checked the abolition before the activity began. Our group recorded the abolitionism in the class notebook. The students checked the abolitionist before the activity began. Our group recorded the abominable in the class notebook. The students checked the abomination before the activity began. Our group recorded the abominations in the class notebook. The students checked the abood before the activity began. Our group recorded the aboodi in the class notebook. The students checked the aboriginal before the activity began.',NULL,NULL,NULL,3,'SPELLING','PUBLISHED',NULL);
