INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('ea65d4ff-e42f-54fd-8610-02cc2361b535','TEXT','Proofreading passage PB','The students checked the aborigine before the activity began. Our group recorded the aborigines in the class notebook. The students checked the aborn before the activity began. Our group recorded the abort in the class notebook. The students checked the aborted before the activity began. Our group recorded the aborting in the class notebook. The students checked the abortion before the activity began. Our group recorded the abortionist in the class notebook. The students checked the abortionists before the activity began.',NULL,NULL,NULL,3,'SPELLING','PUBLISHED',NULL);
